local _, WFJ = ...
WFJ.Data.add("quest", {
  [96016] = { "Le armi della tempesta", "Consegna l'Eye of the Tempest a Bath'rah l'osservatore dei venti, nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", nil, nil, nil, 0x578d0b90, 0x5da19497, nil, nil, nil, "..mmm" },
  [96031] = { "Campeggio 101: Conciatura", nil, "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, nil, 0x86e620e9, nil, nil, ".m.mm" },
  [96044] = { "Campeggio 101: Forgiatura", nil, "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una Sharpening Wheel. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, nil, 0x469a706e, nil, nil, ".m.mm" },
  [96045] = { "Campeggio 101: Alchimia", nil, nil, nil, nil, 0x32f4ba12, nil, nil, nil, nil, ".mmmm" },
  [96046] = { "Campeggio 101: Estrazione", nil, "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una Lodestone per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, nil, 0xa8fe12f3, nil, 0x8ef0fff6, nil, nil, ".m.mm" },
  [96047] = { "Campeggio 101: ⟦First Aid=Primo Soccorso⟧", nil, "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un First Aid Kit per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, nil, 0x6e7c255b, nil, 0x32ff3188, nil, nil, ".m.mm" },
  [96050] = { "Campeggio 101: Pesca", nil, "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Fish Bowl per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto: ora puoi fabbricare un Fish Bowl tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xe0c1c700, nil, 0x1bcf05fd, nil, 0x54727538, ".m.m." },
  [96055] = { "Campeggio 101: Erbalismo", nil, "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un'Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e un'Incense Candle può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco fatto: ora puoi fabbricare un'Incense Candle tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xd7cde71c, nil, 0xe0048777, nil, 0x52608ebe, ".m.m." },
  [96056] = { "Campeggio 101: Scuoiatura", nil, "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una Camp Chair per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, nil, 0x14236b38, nil, 0x1755b1ba, nil, nil, ".m.mm" },
  [96057] = { "Campeggio 101: Sartoria", nil, "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare un Faction Banner per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, nil, 0x49663bd1, nil, nil, ".m.mm" },
  [96058] = { "Campeggio 101: Ingegneria", nil, "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Reagent Bot per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, nil, 0x549b28c0, nil, nil, ".m.mm" },
  [96059] = { "Campeggio 101: Incantamento", nil, nil, nil, nil, 0x2e9b8c15, nil, nil, nil, nil, ".mmmm" },
  [96102] = { "Campeggio 101: Sartoria", nil, "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare un Faction Banner per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, nil, 0x49663bd1, nil, nil, ".m.mm" },
  [96135] = { "Ascolta il mio richiamo", "Usa i totem distorti per porre fine al rituale dei verrospini.", nil, nil, nil, 0xb87aaede, 0x5eafbe6d, nil, nil, nil, "..mmm" },
  [96136] = { "Il richiamo dell'aria", "Trova Prate Cloudseer a ⟦Thousand Needles=Millepicchi⟧.", nil, nil, nil, 0x8f4acf86, 0x7a57cbe0, nil, nil, nil, "..mmm" },
  [96222] = { nil, nil, nil, nil, nil, 0xa9d55f09, nil, nil, nil, nil, "emmmm" },
  [96243] = { "Il richiamo della terra", "Trova Teo Hammerstorm a Dun Morogh.", "È ora che tu dia ascolto alla terra, <valoroso/valorosa> <Sciamano/Sciamana>. Gli elementi già ti pizzicano la pelle, ma una volta che avrai parlato con la pietra, il suolo stesso si farà saldo sotto i tuoi piedi... e nella tua anima.\n\nCerca Teo Hammerstorm nella ⟦Coldridge Valley=Valle Crestafredda⟧. Lo troverai dentro ⟦Anvilmar=Forgiamara⟧, una roccaforte forgiata con martello, fuoco e volontà.", nil, nil, 0xe316c17f, 0xf8e81384, 0x13c0eb8d, nil, nil, "...mm" },
  [96264] = { "Aiuto elementale", "Sconfiggi Charlga Razorflank nelle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧ e raccogli informazioni sui piani dei verrospini.", nil, nil, nil, 0x3a904965, 0xd3648ee8, nil, nil, nil, "..mmm" },
  [96877] = { "Lo zoccolo di Halikor", "Consegna lo Halikor's Hoof a Orgrimmar.", "L'enorme zoccolo è la prova della tua vittoria sulla possente lucertola.", "Sì?", "Che trofeo, {class}! Dev'essere stato un bel combattimento!", 0x795887e1, 0xda5a81ff, 0x4475e6e3, 0x0c07a888, 0x6e0703c3, "....." },
  [96984] = { "Il cuore dello sconvolgimento", nil, nil, nil, nil, 0x0ac2f4b9, nil, nil, nil, nil, ".mmmm" },
})
